const LoginUser = ()=>{
      const  clickHandle = () => {
                alertify.alert('Alert Title', 'Alert Message!', function(){ 
                  alertify.success('Ok'); 
                });
              }
  return <>
         <div onClick={clickHandle}> Este es el login User de Logue</div>
  </>
  }
  export default LoginUser
